const specs={
  'TE Series':'Models include TE46 / TE4Z (4×2) and TE8 / TE9 variants (6×4). Listed battery choices span 400–600 kWh, with peak motor output up to 550 kW and gross combination weight up to 120,000 kg. GB and selected EU charging interfaces are available by model.',
  'KT / KTH Series':'The KT5 platform uses a 4×2 layout with 262 / 310 kWh battery options. Cargo body lengths cover approximately 6.8–9.8 m across the range. KTH variants extend the platform to higher-output, heavy cargo applications.',
  'TZ Series':'Construction models include 6×4 and 8×4 layouts. Listed configurations offer CATL batteries from 352–600 kWh, reinforced multi-layer frames and peak motor output up to 550 kW for demanding duty cycles.',
  'Special Vehicles':'Available chassis support sprinklers, sweepers, refuse collection, waste transfer and concrete mixing. Battery choices range from 166–410 kWh with 4×2, 6×4 and 8×4 configurations.'
};
document.querySelector('.menu').addEventListener('click',e=>{const h=document.querySelector('.topbar');h.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',h.classList.contains('open'))});
document.querySelectorAll('.filters button').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.filters button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');document.querySelectorAll('.product-card').forEach(card=>card.classList.toggle('hidden',btn.dataset.filter!=='all'&&card.dataset.category!==btn.dataset.filter))}));
const dialog=document.querySelector('#specDialog');document.querySelectorAll('.details').forEach(btn=>btn.addEventListener('click',()=>{document.querySelector('#dialogTitle').textContent=btn.dataset.model;document.querySelector('#dialogBody').textContent=specs[btn.dataset.model];dialog.showModal()}));document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
document.querySelector('#quoteForm').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget);const message=encodeURIComponent(`Dongfeng EV inquiry\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nCountry: ${d.get('country')}\nVehicle: ${d.get('vehicle')}\nProject details: ${d.get('message')||'Please contact me with a suitable configuration.'}`);document.querySelector('.form-status').textContent='Opening WhatsApp with your inquiry details…';window.open(`https://wa.me/8618591976330?text=${message}`,'_blank','noopener')});
